/**
 * IntentNav-SCFR: Chromium Network Privacy Evidence Strict Validator
 *
 * Performs standalone, deterministic verification of the empirical evidence
 * generated by real Chromium execution for Patent Claim 11:
 * (evidence/chromium_network_privacy_evidence.json)
 *
 * Enforces strict privacy criteria:
 * 1. File existence & valid JSON syntax
 * 2. Complete schema coverage (assertions, scenariosExecuted, allRequests)
 * 3. Exactly zero external requests (externalRequestsCount === 0)
 * 4. Zero external telemetry / analytics endpoints (externalTelemetryCount === 0)
 * 5. Zero external LLM / AI inference API endpoints (externalInferenceCount === 0)
 * 6. Zero external cloud route synchronization endpoints (externalCloudRoutesCount === 0)
 * 7. 100% of network traffic confined to localhost, chrome-extension://, or local in-memory
 * 8. Zero user data, credentials, or authentication tokens transmitted externally
 * 9. All executed scenarios successfully verified under local-only execution
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, '..');

const EVIDENCE_FILE = path.join(ROOT, 'evidence', 'chromium_network_privacy_evidence.json');

const REQUIRED_ROOT_FIELDS = [
  'runId',
  'timestamp',
  'browserExecutable',
  'browserVersion',
  'environment',
  'runnerType',
  'claimReference',
  'assertions',
  'scenariosExecuted',
  'allRequests',
];

const REQUIRED_ASSERTION_FIELDS = [
  'totalRequestsIntercepted',
  'categorizedEndpoints',
  'externalRequestsCount',
  'externalTelemetryCount',
  'externalInferenceCount',
  'externalCloudRoutesCount',
  'zeroDataLeftLocalhost',
  'zeroCredentialsTransmitted',
  'privacyVerified',
];

function validate() {
  console.log('================================================================');
  console.log('IntentNav-SCFR: Empirical Network Privacy Strict Validator');
  console.log('Validating evidence/chromium_network_privacy_evidence.json (Claim 11)');
  console.log('================================================================\n');

  if (!fs.existsSync(EVIDENCE_FILE)) {
    console.error(`✕ Error: Evidence file not found at ${EVIDENCE_FILE}`);
    process.exit(1);
  }

  let data;
  try {
    const raw = fs.readFileSync(EVIDENCE_FILE, 'utf8');
    data = JSON.parse(raw);
  } catch (err) {
    console.error(`✕ Error parsing evidence JSON: ${err.message}`);
    process.exit(1);
  }

  const errors = [];

  // Check 1: Root schema fields
  for (const field of REQUIRED_ROOT_FIELDS) {
    if (data[field] === undefined || data[field] === null) {
      errors.push(`Missing root field: ${field}`);
    }
  }

  // Check 2: Assertions object completeness
  if (data.assertions && typeof data.assertions === 'object') {
    for (const field of REQUIRED_ASSERTION_FIELDS) {
      if (data.assertions[field] === undefined || data.assertions[field] === null) {
        errors.push(`Missing assertions field: ${field}`);
      }
    }
  } else {
    errors.push('Root field "assertions" is not an object');
  }

  // Check 3: Zero external endpoints
  if (data.assertions) {
    const {
      totalRequestsIntercepted,
      externalRequestsCount,
      externalTelemetryCount,
      externalInferenceCount,
      externalCloudRoutesCount,
      zeroDataLeftLocalhost,
      zeroCredentialsTransmitted,
      privacyVerified,
      categorizedEndpoints,
    } = data.assertions;

    if (typeof totalRequestsIntercepted !== 'number' || totalRequestsIntercepted <= 0) {
      errors.push(`Expected totalRequestsIntercepted > 0, got: ${totalRequestsIntercepted}`);
    }

    if (externalRequestsCount !== 0) {
      errors.push(`VIOLATION: externalRequestsCount must be 0, got: ${externalRequestsCount}`);
    }

    if (externalTelemetryCount !== 0) {
      errors.push(`VIOLATION: externalTelemetryCount must be 0, got: ${externalTelemetryCount}`);
    }

    if (externalInferenceCount !== 0) {
      errors.push(`VIOLATION: externalInferenceCount must be 0, got: ${externalInferenceCount}`);
    }

    if (externalCloudRoutesCount !== 0) {
      errors.push(`VIOLATION: externalCloudRoutesCount must be 0, got: ${externalCloudRoutesCount}`);
    }

    if (zeroDataLeftLocalhost !== true) {
      errors.push(`VIOLATION: zeroDataLeftLocalhost must be true`);
    }

    if (zeroCredentialsTransmitted !== true) {
      errors.push(`VIOLATION: zeroCredentialsTransmitted must be true`);
    }

    if (privacyVerified !== true) {
      errors.push(`VIOLATION: privacyVerified must be true`);
    }

    if (categorizedEndpoints) {
      if (categorizedEndpoints.externalOtherEndpoints !== 0) {
        errors.push(`VIOLATION: externalOtherEndpoints must be 0, got: ${categorizedEndpoints.externalOtherEndpoints}`);
      }
    }
  }

  // Check 4: Individual Request Audit
  if (Array.isArray(data.allRequests)) {
    if (data.allRequests.length === 0) {
      errors.push('No requests recorded in allRequests array');
    }

    const ALLOWED_CLASSIFICATIONS = new Set(['LOCAL_MOCK_ASSET', 'EXTENSION_RESOURCE', 'LOCAL_IN_MEMORY']);

    data.allRequests.forEach((req, idx) => {
      if (!req.requestId || !req.url || !req.method) {
        errors.push(`Request #${idx} missing mandatory requestId, url, or method`);
      }

      if (!ALLOWED_CLASSIFICATIONS.has(req.classification)) {
        errors.push(`Request #${idx} (${req.url}) has forbidden classification: "${req.classification}"`);
      }

      const lower = (req.url || '').toLowerCase();
      if (
        !lower.startsWith('http://localhost:') &&
        !lower.startsWith('http://127.0.0.1:') &&
        !lower.startsWith('chrome-extension://') &&
        !lower.startsWith('data:') &&
        !lower.startsWith('blob:')
      ) {
        errors.push(`Request #${idx} contacts unauthorized external host: "${req.url}"`);
      }
    });
  } else {
    errors.push('Root field "allRequests" must be an array');
  }

  // Check 5: Scenario execution verification
  if (Array.isArray(data.scenariosExecuted)) {
    if (data.scenariosExecuted.length === 0) {
      errors.push('No scenarios recorded in scenariosExecuted');
    }
    data.scenariosExecuted.forEach((sc, idx) => {
      if (!sc.verified) {
        errors.push(`Scenario #${idx} (${sc.scenarioId}) failed execution during privacy capture`);
      }
    });
  } else {
    errors.push('Root field "scenariosExecuted" must be an array');
  }

  if (errors.length > 0) {
    console.error(`✕ Validation FAILED with ${errors.length} error(s):`);
    errors.forEach((err) => console.error(`  - ${err}`));
    process.exit(1);
  }

  const totalReqs = data.allRequests?.length || 0;
  const mockReqs = data.assertions?.categorizedEndpoints?.localMockSiteRequests || 0;
  const extReqs = data.assertions?.categorizedEndpoints?.extensionInternalResources || 0;
  const scenariosCount = data.scenariosExecuted?.length || 0;

  console.log('✓ Validation PASSED: 100% of network privacy criteria satisfied.');
  console.log(`  - Total Intercepted Requests:       ${totalReqs}`);
  console.log(`  - Local Mock Site Requests:         ${mockReqs}`);
  console.log(`  - Extension Internal Resources:     ${extReqs}`);
  console.log(`  - External Telemetry Endpoints:     0`);
  console.log(`  - External Inference API Endpoints: 0`);
  console.log(`  - External Cloud Route Endpoints:   0`);
  console.log(`  - External Requests Count:          0`);
  console.log(`  - Localhost Isolation:              VERIFIED`);
  console.log(`  - Scenarios Successfully Verified:  ${scenariosCount}`);
  console.log('\nEmpirical evidence for Patent Claim 11 is strictly verified.\n');
}

validate();
